import{_ as s,o as n,c as i,a5 as p}from"./chunks/framework.DJo0M80U.js";const r=JSON.parse('{"title":"19. 代码单元的静态链接与动态链接","description":"The Little Book of C 中文版 — 19. 代码单元的静态链接与动态链接","frontmatter":{"title":"19. 代码单元的静态链接与动态链接","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","02-语言基础","中文"],"description":"The Little Book of C 中文版 — 19. 代码单元的静态链接与动态链接","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":19,"sidebarWeight":19,"alternateZh":"/posts/c教程/zh-CN/02-语言基础/019-Static vs Dynamic Linking of Code Units","alternateEn":"/posts/c教程/en-US/02-Language Basics/019-Static vs Dynamic Linking of Code Units"},"headers":[],"relativePath":"posts/c教程/zh-CN/02-语言基础/019-Static vs Dynamic Linking of Code Units.md","filePath":"posts/c教程/zh-CN/02-语言基础/019-Static vs Dynamic Linking of Code Units.md","lastUpdated":1790163617000}'),e={name:"posts/c教程/zh-CN/02-语言基础/019-Static vs Dynamic Linking of Code Units.md"};function t(l,a,c,o,d,h){return n(),i("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/02-Language Basics/019-Static vs Dynamic Linking of Code Units)</p><p>当您的程序超出单个文件时，您开始将位于不同文件中的多个代码单元、函数和数据链接在一起。此链接步骤决定您的程序如何组合和共享代码。 C 语言主要有两种实现方式：静态链接和动态链接。理解两者对于构建现实世界的软件至关重要。</p><h4 id="大局观" tabindex="-1">大局观 <a class="header-anchor" href="#大局观" aria-label="Permalink to &quot;大局观&quot;">​</a></h4><p>当您编译 C 程序时：</p><p>每个<code>.c</code>文件成为目标文件（<code>.o</code>).</p><p>链接器将所有目标文件和库组合成一个可执行文件。</p><p>根据您的链接方式，该可执行文件可能包含：</p><ul><li>所有必需的代码都在里面（静态链接），或者</li><li>对系统上共享库的引用（动态链接）。</li></ul><h4 id="静态链接" tabindex="-1">静态链接 <a class="header-anchor" href="#静态链接" aria-label="Permalink to &quot;静态链接&quot;">​</a></h4><p>静态链接在构建时将所有必要的库代码直接复制到您的程序中。</p><p>命令示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c mathutils.c -o app_static</span></span></code></pre></div><p>一切都来自<code>mathutils.c</code>嵌入内部<code>app_static</code>.</p><p>优点：</p><ul><li>运行时无外部依赖</li><li>启动速度更快（一切都是独立的）</li><li>更容易部署</li></ul><p>缺点：</p><ul><li>更大的可执行文件</li><li>更新库意味着重新编译程序</li></ul><h4 id="动态链接" tabindex="-1">动态链接 <a class="header-anchor" href="#动态链接" aria-label="Permalink to &quot;动态链接&quot;">​</a></h4><p>动态链接（或共享链接）将您的程序链接到共享库（<code>.so</code>在Linux上，<code>.dll</code>在 Windows 上）在运行时而不是嵌入它们。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -o app_dynamic -lm</span></span></code></pre></div><p>这里，<code>-lm</code>告诉链接器使用共享数学库（<code>libm.so</code>).</p><p>您的程序将库分开，在执行时加载它。</p><p>优点：</p><ul><li>较小的可执行文件</li><li>库可以独立更新</li><li>多个程序共享内存中的同一个库</li></ul><p>缺点：</p><ul><li>需要在运行时提供正确的库</li><li>启动速度稍慢</li></ul><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><p>让我们使用一个简单的数学实用程序来演示静态链接与动态链接。</p><p>mathutils.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int add(int a, int b) {</span></span>
<span class="line"><span>    return a + b;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int multiply(int a, int b) {</span></span>
<span class="line"><span>    return a * b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Mathutils.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef MATHUTILS_H</span></span>
<span class="line"><span>#define MATHUTILS_H</span></span>
<span class="line"><span>int add(int a, int b);</span></span>
<span class="line"><span>int multiply(int a, int b);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>主程序</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &quot;mathutils.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int x = 4, y = 5;</span></span>
<span class="line"><span>    printf(&quot;Add: %d\\n&quot;, add(x, y));</span></span>
<span class="line"><span>    printf(&quot;Multiply: %d\\n&quot;, multiply(x, y));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>静态链接构建：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c mathutils.c -o static_app</span></span>
<span class="line"><span>./static_app</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add: 9</span></span>
<span class="line"><span>Multiply: 20</span></span></code></pre></div><p>动态链接构建（使用共享库）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c -fPIC mathutils.c -o mathutils.o</span></span>
<span class="line"><span>gcc -shared -o libmathutils.so mathutils.o</span></span>
<span class="line"><span>gcc main.c -L. -lmathutils -o dynamic_app</span></span>
<span class="line"><span>export LD_LIBRARY_PATH=.</span></span>
<span class="line"><span>./dynamic_app</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add: 9</span></span>
<span class="line"><span>Multiply: 20</span></span></code></pre></div><p>现在您的可执行文件依赖于共享<code>libmathutils.so</code>，同一个库可以被许多其他程序使用。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>链接决定了您的软件如何连接和共享代码。它影响：</p><ul><li>性能和内存使用情况</li><li>部署和可移植性</li><li>当库发生变化时您的程序更新有多容易</li></ul><p>静态链接非常适合小型独立工具。动态链接更适合大型系统、共享组件或依赖系统库（例如<code>libc</code>,<code>libm</code>,<code>pthread</code>).</p><p>理解链接使您成为一名系统思考者，您将知道程序的各个部分如何在二进制级别组合在一起。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>创建<code>mathutils.c</code>和<code>mathutils.h</code>如上所述。 2、静态编译和动态编译；使用比较文件大小<code>ls -lh</code>.</li><li>移动<code>libmathutils.so</code>退出目录并运行<code>./dynamic_app</code>，注意缺少库错误。 4.添加<code>export LD_LIBRARY_PATH=.</code>并再次运行。</li><li>修改<code>multiply()</code>要打印消息，只需重新编译共享库即可看到更改立即生效。</li></ol><p>静态与动态链接是您的 C 程序从“源代码”转移到实际软件的地方，您的逻辑如何成为在任何机器上生存、加载和运行的可执行文件的一部分。</p>`,52)])])}const g=s(e,[["render",t]]);export{r as __pageData,g as default};
